def compressir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    i = 0
    n = len(texto)
    while i < n:
        ch = texto[i]
        j = i + 1
        while j < n and texto[j] == ch:
            j += 1
        count = j - i
        result.append(ch + str(count))
        i = j
    return "".join(result)
